CREATE OR REPLACE FUNCTION public.actualizar_atributos_queja(p_queja_id uuid, p_tipo text, p_area_afectada text, p_fecha_recepcion_gc date, p_numero_oficio_resolucion text, p_observaciones text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_queja public.quejas;
BEGIN
  IF NOT public.app_es_staff() THEN RAISE EXCEPTION 'No autorizado'; END IF;
  IF btrim(coalesce(p_tipo, '')) = '' OR btrim(coalesce(p_area_afectada, '')) = '' THEN
    RAISE EXCEPTION 'Tipo y área afectada son obligatorios';
  END IF;

  UPDATE public.quejas SET
    tipo = btrim(p_tipo),
    area_afectada = btrim(p_area_afectada),
    fecha_recepcion_gc = p_fecha_recepcion_gc,
    numero_oficio_resolucion = nullif(btrim(p_numero_oficio_resolucion), ''),
    observaciones = nullif(btrim(p_observaciones), '')
  WHERE id = p_queja_id
  RETURNING * INTO v_queja;
  IF v_queja.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada'; END IF;

  INSERT INTO public.logs (fecha, usuario_id, accion, modulo, detalle)
  VALUES (now(), public.app_usuario_actual_id(), 'actualizar', 'quejas',
    'Atributos del registro ' || v_queja.folio || ' actualizados');
  RETURN v_queja;
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_transition(p_id uuid, p_expected bigint, p_state text, p_resolution text DEFAULT NULL::text, p_justification text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_reopen text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE q quejas; target text;
BEGIN
 SELECT * INTO q FROM quejas WHERE id=p_id FOR UPDATE;
 IF auth.uid() IS NULL OR NOT (coalesce(app_es_staff(),false) OR (coalesce(app_es_colaborador(),false) AND coalesce(q.responsable_id=app_usuario_actual_id(),false))) THEN RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
 IF q.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada'; END IF;
 IF p_expected IS NULL OR q.revision<>p_expected THEN RAISE EXCEPTION 'Otra persona modificó la queja. Actualiza el expediente antes de guardar.' USING ERRCODE='40001'; END IF;
 SELECT valor_interno INTO target FROM catalogos WHERE modulo='quejas' AND tipo='estado_queja' AND codigo=p_state LIMIT 1;
 IF target IS NULL THEN RAISE EXCEPTION 'Estado no reconocido'; END IF;
 IF q.estado='Recibido' AND target='En Investigación' AND
 (nullif(btrim(p_justification),'') IS NULL OR coalesce(p_owner,q.responsable_id) IS NULL) THEN RAISE EXCEPTION 'Selecciona un responsable y escribe la justificación'; END IF;
 PERFORM public.transicionar_queja(p_id,target,p_resolution,p_justification,p_owner,p_reopen);
 RETURN (SELECT to_jsonb(v) FROM qms_quejas v WHERE id=p_id);
END; $function$

CREATE OR REPLACE FUNCTION public.crear_queja_interna(p_cliente_nombre text, p_email_cliente text, p_categoria text, p_descripcion text, p_prioridad text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_queja public.quejas;
  v_dias integer;
BEGIN
  IF NOT public.app_es_staff() THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  IF btrim(COALESCE(p_cliente_nombre, '')) = '' OR btrim(COALESCE(p_categoria, '')) = '' OR btrim(COALESCE(p_prioridad, '')) = '' THEN
    RAISE EXCEPTION 'Cliente, categoría y prioridad son obligatorios';
  END IF;

  SELECT dias_vencimiento INTO v_dias
  FROM public.sla_config
  WHERE proceso = 'quejas' AND prioridad = btrim(p_prioridad)
  LIMIT 1;

  INSERT INTO public.quejas (
    folio, cliente_nombre, email_cliente, categoria, descripcion,
    prioridad, estado, fecha, fecha_sla
  ) VALUES (
    public.generar_folio_queja(), btrim(p_cliente_nombre), nullif(btrim(p_email_cliente), ''),
    btrim(p_categoria), nullif(btrim(p_descripcion), ''), btrim(p_prioridad),
    'Recibido', now(), now() + make_interval(days => COALESCE(v_dias, 7))
  ) RETURNING * INTO v_queja;

  INSERT INTO public.logs (fecha, usuario_id, accion, modulo, detalle)
  VALUES (now(), public.app_usuario_actual_id(), 'crear', 'quejas', 'Queja interna ' || v_queja.folio || ' creada');

  RETURN v_queja;
END;
$function$

CREATE OR REPLACE FUNCTION public.crear_queja_publica(p_token text, p_cliente_nombre text, p_email_cliente text, p_telefono text, p_categoria text, p_descripcion text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_form formularios_publicos;
  v_folio text;
BEGIN
  SELECT * INTO v_form
  FROM formularios_publicos
  WHERE token = p_token AND activo = true
  LIMIT 1;

  IF v_form.id IS NULL THEN
    RAISE EXCEPTION 'El enlace no es válido o ya no está disponible';
  END IF;

  IF p_cliente_nombre IS NULL OR btrim(p_cliente_nombre) = '' THEN
    RAISE EXCEPTION 'El nombre del quejoso es obligatorio';
  END IF;

  v_folio := generar_folio_queja();

  INSERT INTO quejas (
    folio, cliente_nombre, email_cliente, telefono,
    categoria, descripcion, estado, fecha
  ) VALUES (
    v_folio,
    btrim(p_cliente_nombre),
    p_email_cliente,
    p_telefono,
    p_categoria,
    p_descripcion,
    'Recibido',
    now()
  );

  RETURN v_folio;
END;
$function$

CREATE OR REPLACE FUNCTION public.actualizar_detalles_queja(p_queja_id uuid, p_categoria text DEFAULT NULL::text, p_prioridad text DEFAULT NULL::text, p_responsable_id uuid DEFAULT NULL::uuid, p_notas text DEFAULT NULL::text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_queja public.quejas;
  v_dias integer;
BEGIN
  IF NOT public.app_es_staff() THEN RAISE EXCEPTION 'No autorizado'; END IF;

  SELECT * INTO v_queja FROM public.quejas WHERE id = p_queja_id FOR UPDATE;
  IF v_queja.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada'; END IF;

  IF p_prioridad IS NOT NULL THEN
    SELECT dias_vencimiento INTO v_dias
    FROM public.sla_config WHERE proceso = 'quejas' AND prioridad = btrim(p_prioridad) LIMIT 1;
  END IF;

  UPDATE public.quejas
  SET categoria = COALESCE(nullif(btrim(p_categoria), ''), categoria),
      prioridad = COALESCE(nullif(btrim(p_prioridad), ''), prioridad),
      responsable_id = COALESCE(p_responsable_id, responsable_id),
      notas = COALESCE(p_notas, notas),
      fecha_sla = CASE WHEN p_prioridad IS NULL THEN fecha_sla
        ELSE COALESCE(fecha, now()) + make_interval(days => COALESCE(v_dias, 7)) END
  WHERE id = p_queja_id
  RETURNING * INTO v_queja;

  RETURN v_queja;
END;
